-- Seed data: ISO 3166-1 countries (248 records)
-- Source: world-countries & countries-and-timezones
-- Idempotent: safe to re-run, upserts on iso2.

ON CONFLICT (iso2) DO UPDATE SET
  name = EXCLUDED.name,
  iso3 = EXCLUDED.iso3,
  phone_code = EXCLUDED.phone_code,
  timezone = EXCLUDED.timezone,
  flag_emoji = EXCLUDED.flag_emoji,
  updated_at = NOW();
